    /// The (trigger, structure ID) pairs `version`'s grammar version prints
    /// although the structure is modelled for other triggers (P8b-final),
    /// keyed "CODE^EVT STRUCTURE", with the reason.
    static func generatedPrintedPairs(for version: Version) -> [String: String] {
        switch version.grammarVersion {
        case .v2_7_1:
            return [
                "RSP^K32 RSP_K25": "CH03 section 3.3.63 QBP/RSP - Find Candidates including Visit Information (p 53), a query profile, prints 'Response Trigger: RSP^K32^RSP_K25', while the profile's own response grammar (RSP^K32^RSP_K32: Segment Pattern Response) and Table 0354 v2.7.1 give RSP_K32 (modelled); RSP_K25 is modelled for RSP^K25 (CH15 15.3.7). A message copying the profile row is not structure-checked under RSP_K25 and is never a mismatch (P8b-final F-I1 d; register section E, v2.7.1 not-modelled table)",
            ]
        case .v2_8_2:
            return [
                "RSP^K32 RSP_K25": "CH03 section 3.2.63 QBP/RSP - Find Candidates including Visit Information (p 55), a query profile, prints 'Response Trigger: RSP^K32^RSP_K25', while the profile's own response grammar (RSP^K32^RSP_K32: Segment Pattern Response) and Table 0354 v2.8.2 give RSP_K32 (modelled); RSP_K25 is modelled for RSP^K25 (CH15 15.3.7). A message copying the profile row is not structure-checked under RSP_K25 and is never a mismatch (P8b-final F-I1 d; register section E, v2.8.2 not-modelled table)",
            ]
        default: return [:]
        }
    }

